const inputData = $input.first()?.json || {};

// Catch n8n HTTP Request errors (e.g. 403 Forbidden on expired sessions or network drop)
if (inputData.error) {
  return [{
    json: {
      cart_empty: true,
      session_expired: true,
      item_count: 0,
      currency_symbol: '$',
      message: 'Your cart session has expired or is invalid. Please start a new order.',
      items: [],
      price_breakdown: {
        subtotal: 0,
        sales_tax: 0,
        payment_fee: 0,
        balance_to_pay_on_arrival: 0,
        total_pay_now: 0
      }
    }
  }];
}

let body = inputData;
if (Array.isArray(body)) body = body[0];

// Catch WooCommerce specific session errors
if (body.code === 'woocommerce_rest_cart_invalid_session' || (body.data && body.data.status >= 400)) {
  return [{
    json: {
      cart_empty: true,
      session_expired: true,
      item_count: 0,
      currency_symbol: '$',
      message: 'Your cart session has expired. Please start a new order.',
      items: [],
      price_breakdown: {
        subtotal: 0,
        sales_tax: 0,
        payment_fee: 0,
        balance_to_pay_on_arrival: 0,
        total_pay_now: 0
      }
    }
  }];
}

const items = Array.isArray(body.items) ? body.items : [];

if (items.length === 0) {
  return [{
    json: {
      cart_empty: true,
      item_count: 0,
      currency_symbol: body.totals?.currency_symbol || '$',
      message: 'The cart is currently empty.',
      items: [],
      price_breakdown: {
        subtotal: 0,
        sales_tax: 0,
        payment_fee: 0,
        balance_to_pay_on_arrival: 0,
        total_pay_now: 0
      }
    }
  }];
}

// Helper to safely extract custom metadata from item_data
const getField = (item, labelRegex) => {
  const found = (item.item_data || []).find(f => labelRegex.test(f.name || f.key || ''));
  return found ? found.value : undefined;
};

const minorUnit = body.totals?.currency_minor_unit ?? 2;
const divisor = Math.pow(10, minorUnit);
const toAmount = (raw) => Number(raw || 0) / divisor;

const summarizedItems = items.map(item => ({
  key: item.key,
  service_name: getField(item, /^tour$/i) || getField(item, /boat.*charter/i) || getField(item, /service/i) || item.name,
  passengers: getField(item, /passenger/i) || item.quantity,
  date: getField(item, /date/i),
  pickup_time: getField(item, /pickup.*time/i),
  pickup_location: getField(item, /pickup.*loc/i),
  duration_label: getField(item, /duration/i),
  line_total: toAmount(item.totals?.line_total)
}));

const currencySymbol = body.totals?.currency_symbol || '$';

// Pull fee amounts by key safely
const findFee = (key) => (body.fees || []).find(f => (f.key || f.id || '').toLowerCase().includes(key.toLowerCase()));
const paymentFee = findFee('payment-fee');
const balanceFee = findFee('balance-to-pay-on-arrival') || findFee('balance');

const subtotal = toAmount(body.totals?.total_items);
const salesTax = toAmount(body.totals?.total_tax);
const paymentFeeAmount = paymentFee ? toAmount(paymentFee.totals?.total) : 0;
const balanceOnArrival = balanceFee ? Math.abs(toAmount(balanceFee.totals?.total)) : 0;
const totalPayNow = toAmount(body.totals?.total_price);

return [{
  json: {
    cart_empty: false,
    item_count: summarizedItems.length,
    currency_symbol: currencySymbol,
    items: summarizedItems,
    price_breakdown: {
      subtotal,
      sales_tax: salesTax,
      payment_fee: paymentFeeAmount,
      balance_to_pay_on_arrival: balanceOnArrival,
      total_pay_now: totalPayNow
    }
  }
}];

return [{
  json: {
    cart_empty: true,
    item_count: 0,
    currency_symbol: '$',
    message: 'No cart found yet for this email.',
    items: [],
    price_breakdown: {
      subtotal: 0,
      sales_tax: 0,
      payment_fee: 0,
      balance_to_pay_on_arrival: 0,
      total_pay_now: 0
    }
  }
}];

